Steps:
[AUTH role=ORG_USER]
[GQL-OP setup_me]
  query { me { id } }
[GQL-EXEC setup_me]
[GQL-CAPTURE setup_me.data.me.id → USER_ID]
[GQL-OP progress]
  query {
    loyaltyMissionProgress(storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" first: 50) {
      totalCount
      items {
        missionId name localizedName description bannerUrl startDate endDate missionType
        rewardPoints { amount currency { code } }
        daysRemaining progressId isStarted status currentValue targetValue
        currentMoneyValue { amount currency { code } }
        targetMoneyValue { amount currency { code } }
        percentage completedDate periodStart periodEnd
        items { productId currentQuantity targetQuantity }
      }
    }
  }
[GQL-EXEC progress]

Assertions:
[ERRORS label=progress] errors[] empty {BL}
[COUNT label=progress] data.loyaltyMissionProgress.totalCount > 0 {SPEC}
[DATA label=progress] data.loyaltyMissionProgress.items.0.missionId is non-empty GUID {OBSERVED}
[DATA label=progress] data.loyaltyMissionProgress.items[?missionId=@td(MSN_ORDERVALUE.id)] is non-null {SPEC}

[STATE] store:set (disable) exits 0 and read-back confirms @td(MSN_STORE_SETTINGS.setting_name) = false on {{STORE_ID}} {OBSERVED}
[ERRORS label=progress_off] errors[] empty {SPEC}
[COUNT label=progress_off] data.loyaltyMissionProgress.totalCount = 0 {SPEC}
[STATE] store:set (restore) exits 0 and read-back confirms @td(MSN_STORE_SETTINGS.setting_name) = true on {{STORE_ID}} {OBSERVED}

